use rk3588_boot_support::{DelayUs,Mmio32};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum OtpReadError{InvalidLength,Timeout}
pub fn otp_base_read_words<I:Mmio32+DelayUs>(io:&mut I,base:u64,word_addr:u16,out:&mut[u32])->Result<(),OtpReadError>{let len=out.len();if len==0||len>31{return Err(OtpReadError::InvalidLength)}let status=base+0x84;io.write32(status,15);io.write32(base+4,(((len as u32)&0x1F)<<8)|(((word_addr as u32)&0x3FF)<<16));io.write32(base+8,1);let mut left=10001u32;loop{let s=io.read32(status);if(s&3)==3{break}left-=1;if left==0{return Err(OtpReadError::Timeout)}io.delay_us(1)}io.write32(status,3);for(i,v)in out.iter_mut().enumerate(){*v=io.read32(base+0x20+(i as u64)*4)}Ok(())}
#[cfg(test)]mod tests{use super::*;struct M{status:u32,w:[u32;3]}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{if a&0xFF==0x84{self.status}else if a&0xFF>=0x20{self.w[((a&0xFF)-0x20)as usize/4]}else{0}}fn write32(&mut self,a:u64,v:u32){if a&0xFF==0x84&&v==15{self.status=3}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn read(){let mut m=M{status:0,w:[7,8,9]};let mut o=[0;3];otp_base_read_words(&mut m,0x1000,2,&mut o).unwrap();assert_eq!(o,[7,8,9]);assert_eq!(otp_base_read_words(&mut m,0x1000,0,&mut[]),Err(OtpReadError::InvalidLength));}}
